attributes.screen_custom_css:
/***StyleDiego--HealthSavingsAccoount--07-05-24*****/
[selector='bg-container']{
    background-color: #DEEBFF;
}

[selector='bg-form']{
    /* Permalink - use to edit and share this gradient: https://colorzilla.com/gradient-editor/#bdddf8+0,f6fafe+50,ffffff+50,ffffff+100 */
    background: linear-gradient(to right, rgba(189,221,248,1) 0%,rgba(246,250,254,1) 50%,rgba(255,255,255,1) 50%,rgba(255,255,255,1) 100%); /* W3C, IE10+, FF16+, Chrome26+, Opera12+, Safari7+ */
    padding: 40px;
    max-width: 1287px;
    margin: auto;
    border-radius: 16px;
}

[selector='bg-form-inside']{
    background-color: #FFFFFF;
    border: 1px solid #CDDDEE;
    border-radius: 5px;
    padding: 40px;
}

[selector='bg-form-inside2']{
    /*background-color: #FFFFFF;
    border: 1px solid #CDDDEE;
    border-radius: 5px;*/
    padding: 20px;
}

[selector='bg-Header']{
    background: linear-gradient(45deg, rgba(188,220,248,1) 0%,rgba(188,220,248,1) 40%,rgba(246,249,251,1) 40%,rgba(246,249,251,1) 41%,rgba(13,71,121,1) 41%,rgba(13,71,121,1) 41%,rgba(13,71,121,1) 100%); /* W3C, IE10+, FF16+, Chrome26+, Opera12+, Safari7+ *//* Permalink - use to edit and share this gradient: https://colorzilla.com/gradient-editor/#bcdcf8+0,bcdcf8+40,f6f9fb+40,f6f9fb+41,0d4779+41,0d4779+41,0d4779+100 */
    background: linear-gradient(45deg, rgba(188,220,248,1) 0%,rgba(188,220,248,1) 40%,rgba(246,249,251,1) 40%,rgba(246,249,251,1) 41%,rgba(13,71,121,1) 41%,rgba(13,71,121,1) 41%,rgba(13,71,121,1) 100%); /* W3C, IE10+, FF16+, Chrome26+, Opera12+, Safari7+ */
    -webkit-box-shadow: 10px 10px 4px -6px rgba(179,179,179,1);
    -moz-box-shadow: 10px 10px 4px -6px rgba(179,179,179,1);
    box-shadow: 10px 10px 4px -6px rgba(179,179,179,1);
}
[selector='bg-Footer']{
    background: linear-gradient(45deg, rgba(188,220,248,1) 0%,rgba(188,220,248,1) 40%,rgba(246,249,251,1) 40%,rgba(246,249,251,1) 41%,rgba(13,71,121,1) 41%,rgba(13,71,121,1) 41%,rgba(13,71,121,1) 100%); /* W3C, IE10+, FF16+, Chrome26+, Opera12+, Safari7+ *//* Permalink - use to edit and share this gradient: https://colorzilla.com/gradient-editor/#bcdcf8+0,bcdcf8+40,f6f9fb+40,f6f9fb+41,0d4779+41,0d4779+41,0d4779+100 */
    background: linear-gradientx(45deg, rgba(188,220,248,1) 0%,rgba(188,220,248,1) 40%,rgba(246,249,251,1) 40%,rgba(246,249,251,1) 41%,rgba(13,71,121,1) 41%,rgba(13,71,121,1) 41%,rgba(13,71,121,1) 100%); /* W3C, IE10+, FF16+, Chrome26+, Opera12+, Safari7+ */
    -webkit-box-shadow: 10px 10px 4px -6px rgba(179,179,179,1);
    -moz-box-shadow: 10px 10px 4px -6px rgba(179,179,179,1);
    box-shadow: 10px 10px 4px -6px rgba(179,179,179,1);
    height: 68px;
}
[selector='logo-img']{
    padding: 25px 20px 10px 20px;
}

.hdrTxt {
    text-align: right;
    color: #FFFFFF;
    font-size: 20px;
    font-weight: bold;
    letter-spacing: 0.075rem;
    line-height: 1.2;
    padding-right: 10px;
    padding-top: 5px;
}

.Textlitle{
    color: #9dabb6;
    font-size: 16px;
    font-weight: 600;
    line-height: 24px;
}
.TitleHealth {
    color: #343434;
    font-size: 40px;
    font-weight: 700;
    line-height: 45.6px;
}
.TitleBlue{
    color: #1572C2;
    font-size: 17px;
    font-weight: bold;
    line-height: 24px;
}
.TextField{
    color: #556271;
    font-size: 16px;
    font-weight: 400;
    line-height: 24px;
    letter-spacing: 1px;
}
.TitleSeccion{
    color: #0B3961;
    border-bottom: 2px solid #BCDCF8;
    font-size: 18px;
    font-weight: 600;
    line-height: 35px;
}
.form-group label{
    color: #556271;
    font-size: 15px;
    font-weight: 400;
    line-height: 22.5px;
}
.form-control {
    color: #556271;
    border: 1px solid #CDDDEE;
    border-radius: 8px;
    padding: 20px 10px;
    margin-bottom: 5%;
}
[selector='btn-position'] .btn-primary {
    color: #fff;
    background-color: #1572C2;
    border-color: #1572C2;
    width: 100%;
    font-size: 16px;
    font-weight: 600;
}

[selector='btn-position2'] .btn-primary {
    color: #fff;
    background-color: #1572C2 !important;
    border-color: #1572C2 !important;
    border-radius: 4px !important;
    width: 100% !important;
    font-size: 17px !important;
    font-weight: 600;
    line-height: 24px;
    padding: 8px 10px;
    text-transform: capitalize;
    margin-top: 5%;
}

[selector='btn-position2'] .btn-secondary {
    color: #fff;
    background-color: #6A7888 !important;
    border-color: #6A7888 !important;
    border-radius: 4px !important;
    width: 100% !important;
    font-size: 16px !important;
    font-weight: 400;
    line-height: 24px;
    padding: 8px 10px;
    text-transform: capitalize;
    margin-top: 5%;
}

[selector='btn-position3'] .btn-primary {
    color: #fff;
    background-color: #1572C2 !important;
    border-color: #1572C2!important;
    border-radius: 10px !important;
    width: 100% !important;
    font-size: 19px !important;
    font-weight: 400;
    line-height: 24px;
    text-align: left;
    text-transform: capitalize;
}

[selector='btn-position3'] .btn-light {
    color: #556271;
    background-color: transparent !important;
    border-color: transparent !important;
    border-radius: 24px !important;
    width: 100% !important;
    font-size: 16px !important;
    font-weight: 400;
    line-height: 24px;
    text-align: left;
    text-transform: capitalize;
}
